423	  /* [已核实] classic/sdp.h:654 int bt_sdp_get_proto_param(const struct net_buf *, enum bt_sdp_proto, uint16_t *)；BT_SDP_PROTO_L2CAP=0x0100 见 :639 */
424	
425	  err = bt_sdp_get_proto_param(result->resp_buf, BT_SDP_PROTO_L2CAP, &psm);
