427	    {
428	      pan_fail("sdp: cannot parse L2CAP psm");
429	      return BT_SDP_DISCOVER_UUID_STOP;
430	    }
431	
432	  g_pan.psm = psm;
433	  printf("[pan] SDP ok psm=0x%04x\n", psm);
434	
435	  memset(&g_pan.chan, 0, sizeof(g_pan.chan));
436	  g_pan.chan.chan.ops = &g_pan_l2cap_ops;
437	  g_pan.state = PW_PAN_L2CAP;
438	
439	  err = bt_l2cap_chan_connect(conn, &g_pan.chan.chan, psm);
440	  if (err < 0)
441	    {
442	      printf("[pan] l2cap connect err=%d\n", err);
443	      pan_fail("l2cap connect failed");
444	    }
445	
446	  return BT_SDP_DISCOVER_UUID_STOP;
447	}
